sys_script_include.script:
var CiscoSecureAccessPostConfigurationSetup = Class.create();
CiscoSecureAccessPostConfigurationSetup.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    runSetup: function() {
        // 1. Create or update custom fields on em_event
        function createOrUpdateField(tableName, columnName, label, type, length) {
            var dict = new GlideRecord('sys_dictionary');
            dict.addQuery('name', tableName);
            dict.addQuery('element', columnName);
            dict.query();

            if (dict.next()) {
                var updated = false;
                if (dict.max_length != length) {
                    dict.max_length = length;
                    updated = true;
                }
                if (updated) {
                    dict.update();
                }
            } else {
                var newDict = new GlideRecord('sys_dictionary');
                newDict.initialize();
                newDict.name = tableName;
                newDict.element = columnName;
                newDict.column_label = label;
                newDict.internal_type = type;
                newDict.max_length = length;
                newDict.mandatory = false;
                newDict.active = true;
                newDict.insert();
            }
        }

        // Example fields for em_event
        createOrUpdateField("em_event", "u_api_key", "API Key", "string", 100);
        createOrUpdateField("em_event", "u_rule_name", "Rule Name", "string", 1000);

        // 2. Create or update Event Rule
        function createOrUpdateEventRule(ruleName, condition) {
            var rule = new GlideRecord('em_match_rule');
            rule.addQuery('name', ruleName);
            rule.query();

            if (rule.next()) {
                return "⚠️ Event Rule already exists: " + ruleName;
            }

            rule.initialize();
            rule.name = ruleName;
            rule.sys_name = ruleName;
            rule.description = "Event Rule created via script";
            rule.active = true;
            rule.filter = condition;
            rule.ignore_event = true;
            rule.insert();

            return "✅ Event Rule created: " + ruleName;
        }

        var condition = "severity=3^ORseverity=4^ORseverity=0^ORseverity=5";
        var eventRuleResult = createOrUpdateEventRule("Cisco Secure Access Event Management Rule", condition);

        // 3. Create or update custom fields on em_alert
        function createOrUpdateFieldAlert(tableName, columnName, label, type, length) {
            var dict = new GlideRecord('sys_dictionary');
            dict.addQuery('name', tableName);
            dict.addQuery('element', columnName);
            dict.query();

            if (dict.next()) {
                var updated = false;
                if (dict.max_length != length) {
                    dict.max_length = length;
                    updated = true;
                }
                if (updated) {
                    dict.update();
                }
            } else {
                var newDict = new GlideRecord('sys_dictionary');
                newDict.initialize();
                newDict.name = tableName;
                newDict.element = columnName;
                newDict.column_label = label;
                newDict.internal_type = type;
                newDict.max_length = length;
                newDict.mandatory = false;
                newDict.active = true;
                newDict.insert();
            }
        }

        createOrUpdateFieldAlert("em_alert", "u_api_key", "API Key", "string", 100);
        createOrUpdateFieldAlert("em_alert", "u_rule_name", "Rule Name", "string", 2000);
		// 4. Activate default Alert Management "Create Incident" rule
        var alertAction = new GlideRecord('em_alert_action');
        alertAction.addQuery('name', 'Create Incident'); // adjust if your instance has different name
        alertAction.query();
        if (alertAction.next()) {
            if (!alertAction.active) {
                alertAction.active = true;
                alertAction.update();
                results.push("✅ Activated default Alert Management rule: Create Incident");
            } else {
                results.push("⚠️ Alert Management rule already active: Create Incident");
            }
        } else {
            results.push("❌ Could not find Alert Management rule: Create Incident");
        }

        return "🎯 Cisco Event Setup complete. " + eventRuleResult;
    }
});
